import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p51_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor argmax_dim1_cuda(torch::Tensor input);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("argmax_dim1_cuda", &argmax_dim1_cuda, "Argmax over dim=1 for contiguous float32 3D tensors");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Kernel: each block handles one (batch, col) output element.
// Grid: (batch, col), Block: (BLOCK,)
// Reduces over dim=1 (reduce_size elements), stride between consecutive dim=1 elements = inner_size.
__global__ void argmax_dim1_kernel(
    const float* __restrict__ input,
    int64_t* __restrict__ output,
    int reduce_size,
    int inner_size
) {
    int batch_idx = blockIdx.x;
    int col_idx   = blockIdx.y;

    // Base pointer for this (batch, col) slice along dim=1
    const float* base = input + (int64_t)batch_idx * reduce_size * inner_size + col_idx;

    float  best_val = -FLT_MAX;
    int    best_idx = 0;

    // Each thread strides through the reduction dimension
    for (int i = threadIdx.x; i < reduce_size; i += blockDim.x) {
        float v = base[(int64_t)i * inner_size];
        if (v > best_val) {
            best_val = v;
            best_idx = i;
        }
    }

    // Warp-level reduction using shuffle
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        float  other_val = __shfl_down_sync(mask, best_val, offset);
        int    other_idx = __shfl_down_sync(mask, best_idx, offset);
        if (other_val > best_val || (other_val == best_val && other_idx < best_idx)) {
            best_val = other_val;
            best_idx = other_idx;
        }
    }

    // Collect warp results in shared memory
    extern __shared__ char smem[];
    float* svals = (float*)smem;
    int*   sidxs = (int*)(smem + ((blockDim.x / 32) * sizeof(float)));

    int lane   = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    int num_warps = (blockDim.x + 31) >> 5;

    if (lane == 0) {
        svals[warp_id] = best_val;
        sidxs[warp_id] = best_idx;
    }
    __syncthreads();

    // Final reduction in first warp
    if (threadIdx.x < num_warps) {
        best_val = svals[threadIdx.x];
        best_idx = sidxs[threadIdx.x];
    } else {
        best_val = -FLT_MAX;
        best_idx = 0;
    }

    if (threadIdx.x < 32) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            float  other_val = __shfl_down_sync(mask, best_val, offset);
            int    other_idx = __shfl_down_sync(mask, best_idx, offset);
            if (other_val > best_val || (other_val == best_val && other_idx < best_idx)) {
                best_val = other_val;
                best_idx = other_idx;
            }
        }
        if (threadIdx.x == 0) {
            output[(int64_t)batch_idx * inner_size + col_idx] = (int64_t)best_idx;
        }
    }
}

torch::Tensor argmax_dim1_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.dim() == 3, "input must be 3D for this fast path");

    int batch_size   = input.size(0);
    int reduce_size  = input.size(1);
    int inner_size   = input.size(2);

    auto output = torch::empty({batch_size, inner_size}, input.options().dtype(torch::kInt64));

    const int BLOCK = 256;
    int num_warps = (BLOCK + 31) / 32;
    size_t smem_bytes = num_warps * (sizeof(float) + sizeof(int));

    dim3 grid(batch_size, inner_size);
    dim3 block(BLOCK);

    argmax_dim1_kernel<<<grid, block, smem_bytes>>>(
        input.data_ptr<float>(),
        output.data_ptr<int64_t>(),
        reduce_size,
        inner_size
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Argmax over a specified dimension.
        """
    def __init__(self, dim: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the model with the dimension to perform argmax.

                Args:
                    dim (int): The dimension to perform argmax over.
                """
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if (x.is_cuda and x.dtype == torch.float32 and x.is_contiguous() and x.dim() == 3 and self.dim == 1):
                    return _stark_get_extension().argmax_dim1_cuda(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return torch.argmax(x, dim=self.dim)
        # <<<END_IMPROVE>>>

