CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Each warp handles one output element (one (outer_idx, inner_idx) pair).
// Threads within a warp stride over the reduce dimension.
// Block: THREADS threads = WARPS_PER_BLOCK warps.
// Grid: ceil(outer * inner / WARPS_PER_BLOCK) blocks.

#define THREADS 256
#define WARP_SIZE 32
#define WARPS_PER_BLOCK (THREADS / WARP_SIZE)

__global__ void argmax_dim1_warp_kernel(
    const float* __restrict__ input,
    int64_t* __restrict__ output,
    int outer,
    int reduce,
    int inner
) {
    int warp_id = threadIdx.x / WARP_SIZE;
    int lane    = threadIdx.x % WARP_SIZE;
    int global_warp = (int)blockIdx.x * WARPS_PER_BLOCK + warp_id;
    int total_outputs = outer * inner;
    if (global_warp >= total_outputs) return;

    int outer_idx = global_warp / inner;
    int inner_idx = global_warp % inner;

    // Base pointer for this (outer_idx, inner_idx) slice along dim=1
