    if (remainder > 0) {
        int tail_start = full_tiles * TILE;
        dim3 block(BLOCK_X, 1);
        dim3 grid((remainder + BLOCK_X - 1) / BLOCK_X, outer);
        argmax_dim1_tail_kernel<<<grid, block, 0, stream>>>(
            input.data_ptr<float>(),
            output.data_ptr<int64_t>(),
            outer, reduce, inner, tail_start
        );
    }

